@staticmethod
def get_component_source(key: str) -> str:
    """Return a human-readable source description for a component.

    Runtime-inferred — no hardcoded mapping.  Checks (in order):
    1. Has a ``_build_{key}()`` method  → function name
    2. Has a ``~/.nanobot/prompts/{key}.md`` file → filename
    3. Is a known agent-dict field        → field name
    4. Fallback                           → "runtime"
    """
    # 1. Check for a _build_xxx() method on the class
    method_name = f"_build_{key}"
    if hasattr(PromptBuilder, method_name):
        return f"{method_name}()"

    # 2. Check for a template .md file
    f = Path.home() / ".nanobot" / "prompts" / f"{key}.md"
    if f.exists():
        return f"{key}.md"

    # 3. Known agent-dict fields
    _AGENT_FIELDS = {
        "examples", "instructions", "persona",
        "main_prompt", "group_context",
    }
    if key in _AGENT_FIELDS:
        return f"agent.{key}"

    return "runtime"

